def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: Point instance or tuple/list
    :type value: Point
    :return: dict or list representation
    """
    if value is None:
        return None

    # If the object provides a to_dict method, use it
    if hasattr(value, "to_dict") and callable(value.to_dict):
        try:
            return value.to_dict()
        except Exception as exc:
            raise ValueError(f"Error converting Point to dict: {exc}") from exc

    # Try to extract x, y, (and optionally z) attributes
    if hasattr(value, "x") and hasattr(value, "y"):
        result = {"x": getattr(value, "x"), "y": getattr(value, "y")}
        if hasattr(value, "z"):
            result["z"] = getattr(value, "z")
        return result

    # Handle tuple or list representations
    if isinstance(value, (tuple, list)):
        if len(value) == 2:
            return {"x": value[0], "y": value[1]}
        if len(value) == 3:
            return {"x": value[0], "y": value[1], "z": value[2]}
        raise ValueError(f"Unsupported tuple/list length for Point: {len(value)}")

    # Try to iterate over the value if it is iterable
    if hasattr(value, "__iter__"):
        try:
            items = list(value)
            if len(items) == 2:
                return {"x": items[0], "y": items[1]}
            if len(items) == 3:
                return {"x": items[0], "y": items[1], "z": items[2]}
        except Exception:
            pass

    raise TypeError(f"Unsupported type for Point dehydration: {type(value).__name__}")

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Attempt to locate a common attribute that holds the record data
    record = None
    if hasattr(self, "_record"):
        record = self._record
    elif hasattr(self, "record"):
        record = self.record
    elif hasattr(self, "data"):
        record = self.data

    # If we found a record, try to get its keys
    if record is not None:
        try:
            return list(record.keys())
        except AttributeError:
            # Not a mapping; try to iterate over it directly
            try:
                return list(record)
            except Exception:
                pass

    # Fallback: if the object itself behaves like a mapping
    if isinstance(self, dict):
        return list(dict.__iter__(self))

    # Final fallback: return the object's own attribute names
    return list(self.__dict__.keys())

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        for idx, item in enumerate(self):
            if item == key:
                return idx
    except TypeError as exc:
        raise TypeError("Object is not iterable") from exc
    raise ValueError(f"{key!r} is not in list")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine the underlying items of the record.
    # Prefer a dict-like interface if available, otherwise treat the
    # object itself as an iterable of (key, value) pairs.
    if hasattr(self, "items") and callable(self.items):
        try:
            items = list(self.items())
        except Exception as exc:
            raise TypeError("Unable to retrieve items from the record") from exc
    else:
        try:
            items = list(self)
        except Exception as exc:
            raise TypeError("Record object is not iterable") from exc

    # If no keys are specified, return all values.
    if not keys:
        return [value for _, value in items]

    # Otherwise, filter based on the provided keys.
    result = []
    for key in keys:
        if isinstance(key, int):
            # Treat as an index into the items list.
            try:
                result.append(items[key][1])
            except IndexError as exc:
                raise IndexError(f"Index {key} out of range for record values") from exc
        else:
            # Treat as a key lookup.
            found = False
            for k, v in items:
                if k == key:
                    result.append(v)
                    found = True
                    break
            if not found:
                raise KeyError(f"Key {key!r} not found in record")
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Ensure the record has the expected internal structure
    if not hasattr(self, "_keys") or not hasattr(self, "_data"):
        raise AttributeError("Record object must have '_keys' and '_data' attributes")

    # If no keys are specified, return all fields
    if not keys:
        return dict(zip(self._keys, self._data))

    result = {}
    for k in keys:
        # Handle integer indices
        if isinstance(k, int):
            if k < 0 or k >= len(self._data):
                raise IndexError(f"Index {k} out of bounds for record of length {len(self._data)}")
            key_name = self._keys[k]
            result[key_name] = self._data[k]
        else:
            # Treat as a field name
            if k in self._keys:
                idx = self._keys.index(k)
                result[k] = self._data[idx]
            else:
                result[k] = None
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    # Validate inputs
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple, dict)):
        raise TypeError("fields must be a list, tuple, or dict")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Prepare class dictionary
    class_dict = {}

    # Handle fields
    if isinstance(fields, dict):
        for key, value in fields.items():
            if not isinstance(key, str):
                raise TypeError("field names must be strings")
            class_dict[key] = value
    else:
        for key in fields:
            if not isinstance(key, str):
                raise TypeError("field names must be strings")
            class_dict[key] = None

    # Add SRID_MAP as a class attribute
    class_dict['SRID_MAP'] = srid_map

    # Optionally add a simple __init__ that accepts keyword arguments
    def __init__(self, **kwargs):
        for k, v in kwargs.items():
            if k in class_dict:
                setattr(self, k, v)
            else:
                raise AttributeError(f"Unknown attribute '{k}' for {name}")
    class_dict['__init__'] = __init__

    # Create the new subclass of Point
    try:
        new_cls = type(name, (Point,), class_dict)
    except Exception as e:
        raise RuntimeError(f"Failed to create Point subclass '{name}': {e}") from e

    return new_cls

