    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    if cache is None:
        raise ValueError("cache must not be None")
    def decorator(func):
        def wrapper(*args, **kwargs):
            # compute cache key
            try:
                k = key(args, kwargs)
            except Exception as exc:
                raise ValueError("Key function raised an exception") from exc
            # try to retrieve from cache
            try:
                if k in cache:
                    return cache[k]
            except Exception as exc:
                raise ValueError("Cache lookup failed") from exc
            # compute result
            result = func(*args, **kwargs)
            # store in cache
            try:
                if lock:
                    with lock:
                        cache[k] = result
                else:
                    cache[k] = result
            except Exception as exc:
                raise ValueError("Cache store failed") from exc
            return result
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

