def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default
    except TypeError:
        # key not hashable or other type error
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    if cache is None:
        raise ValueError("cache must be a dict-like object")
    if not callable(key):
        raise ValueError("key must be a callable that returns a hashable key")

    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                k = key(*args, **kwargs)
            except Exception as exc:
                raise ValueError(f"Key function raised an exception: {exc}") from exc

            # Thread‑safe access if a lock is provided
            if lock:
                # Support both context‑manager locks and simple acquire/release
                if hasattr(lock, "__enter__") and hasattr(lock, "__exit__"):
                    with lock:
                        if k in cache:
                            return cache[k]
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
                else:
                    lock.acquire()
                    try:
                        if k in cache:
                            return cache[k]
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
                    finally:
                        lock.release()
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result

        # Preserve function metadata without importing functools
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

@staticmethod
    def file_to_textbuffer(file_name, encoding):
        """
        Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
        CAUTION : This will read the whole file IN MEMORY.
        :param file_name: File name.
        :type file_name: str
        :param encoding: Encoding to use.
        :type encoding: str
        :return: A text buffer or None in case of error.
        :rtype str
        """
        # Validate input types
        if not isinstance(file_name, str) or not isinstance(encoding, str):
            return None
        try:
            with open(file_name, 'r', encoding=encoding) as f:
                return f.read()
        except (OSError, UnicodeDecodeError, TypeError):
            return None

@staticmethod
def is_file_exist(file_name):
    """Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        import os
    except ImportError:
        return False
    try:
        return os.path.isfile(file_name)
    except Exception:
        return False

@classmethod
def _reset_logging(cls):
    """Reset logging configuration to default state."""
    try:
        root = logging.getLogger()
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        root.setLevel(logging.WARNING)
        logging.basicConfig(level=logging.WARNING)
    except Exception as e:
        raise RuntimeError(f"Failed to reset logging: {e}") from e

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = self.__class__.__name__
    # Remove any trailing 'Py' or 'Fallback' suffixes, possibly multiple
    while name.endswith('Py') or name.endswith('Fallback'):
        if name.endswith('Py'):
            name = name[:-2]
        elif name.endswith('Fallback'):
            name = name[:-8]
    return name

