def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        raise TypeError("classes must be an iterable of types, got None")
    try:
        iter(classes)
    except TypeError:
        raise TypeError(f"classes must be an iterable of types, got {type(classes).__name__}")
    result = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Expected a type, got {type(cls).__name__}")
        if cls in seen:
            continue
        # Check if any other class in the list is a subclass of this one
        is_super = False
        for other in classes:
            if other is cls:
                continue
            if isinstance(other, type) and issubclass(other, cls):
                is_super = True
                break
        if not is_super:
            result.append(cls)
            seen.add(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("Parameter 'all' must be a boolean value")

    result = {}
    cls = self.__class__

    # Attempt to retrieve an interface definition if present
    interface = getattr(cls, "__interface__", None)
    if interface:
        # If the interface is a mapping of name -> description
        if isinstance(interface, dict):
            for name, desc in interface.items():
                if isinstance(desc, str):
                    result[name] = desc
                else:
                    # Fallback: convert non-string descriptions to string
                    result[name] = str(desc)
        # If the interface is an iterable of attribute names
        elif isinstance(interface, (list, tuple, set)):
            for name in interface:
                try:
                    attr = getattr(cls, name)
                except Exception:
                    continue
                desc = getattr(attr, "__doc__", None)
                if desc is None:
                    desc = ""
                result[name] = desc
        # Other interface formats are ignored

    if all:
        # Include all public attributes that are not methods
        for name in dir(cls):
            if name.startswith("_"):
                continue
            if name in result:
                continue
            try:
                attr = getattr(cls, name)
            except Exception:
                continue
            if callable(attr):
                continue
            desc = getattr(attr, "__doc__", None)
            if desc is None:
                desc = ""
            result[name] = desc

    return result

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If sequence is None, nothing to do
    if sequence is None:
        return output

    # Treat strings and bytes as atomic values
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
        return output

    # Try to iterate over the sequence; if it fails, treat it as a single item
    try:
        iterator = iter(sequence)
    except TypeError:
        output.append(sequence)
        return output

    for item in iterator:
        # If the item itself is a tuple or list, recurse to flatten it
        if isinstance(item, (tuple, list)):
            _normalizeargs(item, output)
        else:
            output.append(item)

    return output

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    try:
        required = _c_optimizations_required()
    except Exception as e:
        raise RuntimeError("Unable to determine if optimizations are required") from e
    return not required

def _c_optimizations_required():
    """Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is True, we are running in pure Python mode and
        # C optimizations are not required. Otherwise, they are required.
        return not bool(PURE_PYTHON)
    except NameError:
        # If the variable is not defined, assume C optimizations are needed.
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context
    self.context = {}

    # Reinitialize bins
    try:
        # If an initial value is defined, use it to reset existing bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                # Preserve the number of bins
                self.bins = [self.initial_value] * len(self.bins)
            else:
                # No existing bins – create a single bin with the initial value
                self.bins = [self.initial_value]
        else:
            # No initial value – fall back to the make_bins method
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # If make_bins is not available, default to an empty list
                self.bins = []
    except Exception as exc:
        # If anything goes wrong during reset, raise a clear error
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # The error indices are expected to be stored in a dictionary
    # attribute named `_err_indices`.  If the attribute is missing
    # or not a dictionary, we treat it as if there are no errors.
    err_dict = getattr(self, "_err_indices", {})
    if not isinstance(err_dict, dict):
        return []
    # Return a copy to prevent accidental external mutation
    return list(err_dict.get(coord_name, []))

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation
    if bins is None or edges is None:
        raise ValueError("Both bins and edges must be provided")
    try:
        bins = list(bins)
        edges = list(edges)
    except TypeError:
        raise ValueError("bins and edges must be iterable")

    if len(edges) != len(bins) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    # Ensure edges are sorted ascending
    for i in range(len(edges) - 1):
        if edges[i] > edges[i + 1]:
            raise ValueError("Edges must be in ascending order")

    # Compute bin widths
    widths = []
    for i in range(len(edges) - 1):
        try:
            width = float(edges[i + 1]) - float(edges[i])
        except (TypeError, ValueError):
            raise ValueError("Edge values must be numeric")
        if width < 0:
            raise ValueError("Negative bin width encountered")
        widths.append(width)

    # Compute integral as sum of bin values times widths
    total = 0.0
    for b, w in zip(bins, widths):
        try:
            val = float(b)
        except (TypeError, ValueError):
            raise ValueError("Bin values must be numeric")
        total += val * w

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Guard against None or non-iterable inputs
    if seq is None:
        return False
    # If seq itself is a Source instance, reject
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source class not defined; assume not a Source
        pass
    # If seq is a single FillRequest instance, accept
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest class not defined; cannot determine
        pass
    # If seq is iterable, check for any FillRequest element
    try:
        for item in seq:
            try:
                if isinstance(item, FillRequest):
                    return True
            except NameError:
                # If FillRequest not defined, skip check
                continue
    except TypeError:
        # seq is not iterable
        return False
    return False

