def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re

    # Regular expressions for keys and values. Adjust as needed.
    LABEL_KEY_REGEX = r'^[A-Za-z0-9_-]+$'
    LABEL_VALUE_REGEX = r'^[A-Za-z0-9_-]+$'

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue

        key_str = key.decode() if isinstance(key, bytes) else key
        if not re.match(LABEL_KEY_REGEX, key_str):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex [{LABEL_KEY_REGEX}]"})

        # Validate value(s)
        def _add_value_error(val):
            if not isinstance(val, (str, bytes)):
                errors.append({str(val): 'expected string or bytes-like object'})
            else:
                val_str = val.decode() if isinstance(val, bytes) else val
                if not re.match(LABEL_VALUE_REGEX, val_str):
                    errors.append({val_str: f"Label value '{val_str}' does not match the regex [{LABEL_VALUE_REGEX}]"})

        if isinstance(value, (str, bytes)):
            _add_value_error(value)
        elif isinstance(value, list):
            for v in value:
                _add_value_error(v)
        else:
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(messages=errors)

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    import re

    # Ensure the value is a string
    if not isinstance(value, str):
        raise ValidationError("Value must be a string")

    # Retrieve the regular expression pattern
    try:
        pattern = REGEX
    except NameError:
        raise ValidationError("No regular expression defined for validation")

    if pattern is None:
        raise ValidationError("Regular expression pattern is None")

    # Compile the pattern if it is a string
    if isinstance(pattern, str):
        try:
            regex = re.compile(pattern)
        except re.error as e:
            raise ValidationError(f"Invalid regular expression: {e}")
    else:
        # Assume pattern is already a compiled regex-like object
        regex = pattern

    # Perform full match
    try:
        if not regex.fullmatch(value):
            raise ValidationError(f"Value '{value}' does not match the required pattern")
    except Exception as e:
        # Catch any unexpected errors during matching
        raise ValidationError(f"Error during validation: {e}")
    # If validation passes, simply return None
    return None

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
