            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")
    if not isinstance(first_level, bool):
        raise TypeError("first_level must be a bool")

    # Fields that should be copied verbatim when at the top level
    identifying_fields = {"apiVersion", "kind", "metadata"}

    def _process(value, is_top):
        if isinstance(value, dict):
            result = {}
            for k, v in value.items():
                if is_top and k in identifying_fields:
                    result[k] = v
                    continue
                if isinstance(v, dict):
                    result[k] = _process(v, False)
                elif isinstance(v, list):
                    new_list = []
                    for item in v:
                        if isinstance(item, dict):
                            new_list.append(_process(item, False))
                        else:
                            new_list.append(None)
                    result[k] = new_list
                else:
                    result[k] = None
            return result
        elif isinstance(value, list):
            return [ _process(item, False) if isinstance(item, dict) else None for item in value ]
        else:
            return None

    return _process(manifest_dict, first_level)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Basic type checks
    if not isinstance(last_applied_manifest, list):
        raise TypeError(
            f"last_applied_manifest must be a list, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(observer_schema, list):
        raise TypeError(
            f"observer_schema must be a list, got {type(observer_schema).__name__}"
        )
    if not isinstance(response, list):
        raise TypeError(
            f"response must be a list, got {type(response).__name__}"
        )

    # Ensure the manifest list is long enough
    if len(last_applied_manifest) < len(response):
        # Extend with empty dicts
        last_applied_manifest.extend([{} for _ in range(len(response) - len(last_applied_manifest))])

    # Iterate over each item in the response
    for idx, resp_item in enumerate(response):
        # Skip if the response item is not a dict
        if not isinstance(resp_item, dict):
            continue

        # Ensure we have a dict in the manifest at this index
        if not isinstance(last_applied_manifest[idx], dict):
            last_applied_manifest[idx] = {}

        # Get the corresponding schema for this item
        try:
            schema_item = observer_schema[idx]
        except IndexError:
            # No schema defined for this index; skip
            continue

        # If the schema item is a dict, recurse into dict handler
        if isinstance(schema_item, dict):
            # Import lazily to avoid circular imports
            try:
                from .manifest_utils import update_last_applied_manifest_dict_from_resp
            except Exception:
                # If the helper is not available, skip nested processing
                continue
            try:
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[idx], schema_item, resp_item
                )
            except Exception as exc:
                # Wrap any exception to provide context
                raise RuntimeError(
                    f"Failed to update nested dict at index {idx}: {exc}"
                ) from exc
            continue

        # If the schema item is a list, treat each element as a key
        if isinstance(schema_item, list):
            for key in schema_item:
                if not isinstance(key, str):
                    continue
                if key not in last_applied_manifest[idx] and key in resp_item:
                    last_applied_manifest[idx][key] = resp_item[key]
            continue

        # If the schema item is a string, treat it as a single key
        if isinstance(schema_item, str):
            key = schema_item
            if key not in last_applied_manifest[idx] and key in resp_item:
                last_applied_manifest[idx][key] = resp_item[key]
            continue

        # If schema_item is of an unexpected type, skip
        continue

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    lines = []
    # Handle common container types
    if isinstance(status, dict):
        for key, value in status.items():
            lines.append(f"{key}: {value}")
    elif isinstance(status, (list, tuple)):
        for item in status:
            if isinstance(item, tuple) and len(item) == 2:
                lines.append(f"{item[0]}: {item[1]}")
            else:
                lines.append(str(item))
    else:
        # Fallback: treat as a single string or other object
        lines.append(str(status))
    # Prefix each line if needed
    if prefix:
        prefixed_lines = [prefix + line for line in lines]
    else:
        prefixed_lines = lines
    return '\n'.join(prefixed_lines)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    log = getattr(self, 'validation_log', None)
    if not log:
        return ''
    lines = []
    if isinstance(log, dict):
        for key, value in log.items():
            if isinstance(value, (list, tuple)):
                for msg in value:
                    lines.append(f"{prefix}{key}: {msg}")
            else:
                lines.append(f"{prefix}{key}: {value}")
    else:
        for entry in log:
            if isinstance(entry, (list, tuple)):
                for msg in entry:
                    lines.append(prefix + str(msg))
            elif hasattr(entry, 'message'):
                lines.append(prefix + str(entry.message))
            else:
                lines.append(prefix + str(entry))
    return '\n'.join(lines)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Helper to check version format
    def _is_valid_version(v):
        if not isinstance(v, str):
            return False
        parts = v.split('.')
        return len(parts) == 2 and all(part.isdigit() for part in parts)

    # Basic type checks
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict-like object")
    if not isinstance(extract_spec_version, bool):
        raise TypeError("extract_spec_version must be a bool")

    # Determine spec_version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get('type')
        if isinstance(type_val, str):
            # Expect format like 'foLiA-1.0' or similar
            if '-' in type_val:
                _, ver = type_val.rsplit('-', 1)
                if _is_valid_version(ver):
                    spec_version = ver

    # Validate spec_version format
    if not _is_valid_version(spec_version):
        raise ValueError(f"Invalid specification version: {spec_version!r}")

    # Inventory must contain spec_version key matching the determined version
    inv_spec = inventory.get('spec_version')
    if inv_spec is None:
        raise ValueError("inventory missing 'spec_version' key")
    if inv_spec != spec_version:
        raise ValueError(f"Inventory spec_version {inv_spec!r} does not match expected {spec_version!r}")

    # Inventory must contain elements list
    elements = inventory.get('elements')
    if elements is None:
        raise ValueError("inventory missing 'elements' key")
    if not isinstance(elements, list):
        raise ValueError("'elements' must be a list")

    # Optional: basic check on each element
    for idx, elem in enumerate(elements):
        if not isinstance(elem, dict):
            raise ValueError(f"Element at index {idx} is not a dict")
        if 'id' not in elem:
            raise ValueError(f"Element at index {idx} missing 'id' key")
        if 'type' not in elem:
            raise ValueError(f"Element at index {idx} missing 'type' key")

    # All checks passed
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an InventoryValidator instance
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Verify that both objects have the required attributes
    required_attrs = ("version", "items")
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"self object missing required attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"prior object missing required attribute '{attr}'")

    # Compare versions – prior must be strictly older
    try:
        if prior.version >= self.version:
            raise ValueError("prior version must be less than current version")
    except Exception as exc:
        raise TypeError(f"Unable to compare versions: {exc}")

    # Determine the set of items for comparison
    try:
        if isinstance(prior.items, (set, list, tuple)):
            prior_items = set(prior.items)
        else:
            prior_items = set(prior.items.keys())
    except Exception as exc:
        raise ValueError(f"Error accessing prior items: {exc}")

    try:
        if isinstance(self.items, (set, list, tuple)):
            self_items = set(self.items)
        else:
            self_items = set(self.items.keys())
    except Exception as exc:
        raise ValueError(f"Error accessing current items: {exc}")

    # Ensure all prior items exist in the current inventory
    missing = prior_items - self_items
    if missing:
        raise ValueError(f"Current inventory is missing items present in prior: {missing}")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping logical paths to versioned content files")
    if not isinstance(version, (int, str)):
        raise TypeError("version must be an int or str")

    result = {}
    for logical_path, versions in inventory.items():
        # Skip malformed entries
        if not isinstance(versions, dict):
            continue

        # Only consider logical paths that exist in the requested version
        if version not in versions:
            continue

        # Collect all content files for this logical path across all versions
        files = set()
        for v, content_file in versions.items():
            if content_file is not None:
                files.add(content_file)

        if files:
            result[logical_path] = files

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if fixity is None:
        raise ValueError("fixity cannot be None")
    if not isinstance(fixity, dict):
        raise TypeError(f"fixity must be a dict, got {type(fixity).__name__}")

    if manifest_files is None:
        raise ValueError("manifest_files cannot be None")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise TypeError(f"manifest_files must be a set, list, or tuple, got {type(manifest_files).__name__}")

    # Required keys in the fixity block
    required_keys = {"file", "hash", "algorithm"}
    missing_keys = required_keys - fixity.keys()
    if missing_keys:
        raise ValueError(f"Missing required keys in fixity block: {missing_keys}")

    # Validate file reference
    file_name = fixity["file"]
    if not isinstance(file_name, str):
        raise TypeError(f"fixity['file'] must be a string, got {type(file_name).__name__}")
    if file_name not in manifest_files:
        raise ValueError(f"File '{file_name}' referenced in fixity is not present in the manifest")

    # Validate hash value
    hash_value = fixity["hash"]
    if not isinstance(hash_value, str):
        raise TypeError(f"fixity['hash'] must be a string, got {type(hash_value).__name__}")

    # Validate algorithm
    algorithm = fixity["algorithm"]
    if not isinstance(algorithm, str):
        raise TypeError(f"fixity['algorithm'] must be a string, got {type(algorithm).__name__}")
    known_algorithms = {"md5", "sha1", "sha256", "sha512"}
    if algorithm.lower() not in known_algorithms:
        raise ValueError(f"Unknown hash algorithm '{algorithm}'. Known algorithms: {sorted(known_algorithms)}")

    # All checks passed
    return True

def files_list(path):
    """Return the files in `path`."""
    import os
    if not isinstance(path, (str, bytes, os.PathLike)):
        raise TypeError("path must be a string or path-like object")
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"Path does not exist: {path}")
        if not os.path.isdir(path):
            raise NotADirectoryError(f"Path is not a directory: {path}")
        entries = os.listdir(path)
    except OSError as e:
        raise RuntimeError(f"Error accessing directory {path}: {e}") from e
    files = []
    for entry in entries:
        full = os.path.join(path, entry)
        if os.path.isfile(full):
            files.append(entry)
    return files

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if content is None:
        return None
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise RuntimeError("Error while replacing namespace prefix") from e

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None:
        raise ValueError("node cannot be None")
    if not hasattr(node, "xpath"):
        raise TypeError("node must support xpath() method")
    if not isinstance(pubdate_xpaths, (list, tuple)):
        raise TypeError("pubdate_xpaths must be a list or tuple of XPath strings")

    for xpath_expr in pubdate_xpaths:
        try:
            result = node.xpath(xpath_expr)
            if result:
                return result[0]
        except Exception:
            # Ignore malformed XPath expressions or evaluation errors
            continue
    return None

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Validate parameters
    if not isinstance(indent, int):
        raise TypeError("indent must be an integer")
    if not isinstance(debug, bool):
        raise TypeError("debug must be a boolean")

    try:
        indent_str = '    ' * max(indent, 0)
        parts = []

        # Header with class name and optional id
        header = f"{self.__class__.__name__}"
        if hasattr(self, "id"):
            header += f" (id={self.id})"
        if debug:
            header += f" {repr(self)}"
        parts.append(indent_str + header)

        # Attempt to pretty-print children if any
        children = None
        if hasattr(self, "children"):
            children = self.children
        elif hasattr(self, "__iter__") and not isinstance(self, (str, bytes, dict, list, tuple, set)):
            children = self

        if children is not None:
            for child in children:
                if isinstance(child, (str, bytes)):
                    parts.append(indent_str + '    ' + repr(child))
                else:
                    try:
                        parts.append(child.pretty(indent + 1, debug))
                    except Exception as e:
                        parts.append(indent_str + '    ' + f"<Error prettying child: {e}>")

        return "\n".join(parts)
    except Exception as e:
        return f"<Error prettying object: {e}>"

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper functions to work with both tuple and object representations
    def _is_binary(expr):
        return (
            hasattr(expr, "operator") and expr.operator in ("&", "|")
            or isinstance(expr, tuple)
            and len(expr) == 3
            and expr[0] in ("&", "|")
        )

    def _is_unary(expr):
        return (
            hasattr(expr, "operator") and expr.operator == "~"
            or isinstance(expr, tuple)
            and len(expr) == 2
            and expr[0] == "~"
        )

    def _op(expr):
        return expr.operator if hasattr(expr, "operator") else expr[0]

    def _left(expr):
        return expr.left if hasattr(expr, "left") else expr[1]

    def _right(expr):
        return expr.right if hasattr(expr, "right") else expr[2]

    def _make_binary(op, left, right):
        # Preserve original representation if possible
        if isinstance(left, tuple) or isinstance(right, tuple):
            return (op, left, right)
        # If the original expression was an object, try to construct a new one
        # using the same class if it accepts operator, left, right arguments.
        try:
            return type(left)(op, left, right)
        except Exception:
            return (op, left, right)

    # Validate input
    if args is None:
        return []
    try:
        iterable = list(args)
    except TypeError:
        raise TypeError("args must be an iterable of expressions")

    new_args = []
    for e in iterable:
        # Only attempt simplification on binary expressions
        if not _is_binary(e):
            new_args.append(e)
            continue

        op = _op(e)
        left = _left(e)
        right = _right

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        import importlib.metadata as metadata
    except Exception:
        return {"version": "unknown"}
    pkg = __package__ or __name__
    try:
        version = metadata.version(pkg)
    except Exception:
        return {"version": "unknown"}
    return {"version": version}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(style, str):
        raise TypeError("style must be a string")

    # Normalize pieces to an iterable
    if isinstance(pieces, (str, bytes)):
        pieces = [pieces]
    try:
        iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of renderable objects")

    rendered_parts = []
    for piece in pieces:
        if piece is None:
            continue

        # If the piece knows how to render itself, use that
        if hasattr(piece, "render") and callable(piece.render):
            try:
                rendered_parts.append(piece.render(style))
                continue
            except Exception:
                # Fall back to string conversion if rendering fails
                pass

        # Default: convert to string
        rendered_parts.append(str(piece))

    return "".join(rendered_parts)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if pieces is None:
        return '+'
    try:
        for p in pieces:
            if p == '+':
                return '.'
    except TypeError:
        raise TypeError("pieces must be an iterable of elements that can be compared to '+'")
    return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate commands
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")
    if not commands:
        raise ValueError("commands cannot be empty")
    for cmd_part in commands:
        if not isinstance(cmd_part, str):
            raise TypeError("each command part must be a string")

    # Validate args
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")
    for arg in args:
        if not isinstance(arg, str):
            raise TypeError("each argument must be a string")

    # Validate cwd
    if cwd is not None:
        if not isinstance(cwd, str):
            raise TypeError("cwd must be a string path or None")
        if not os.path.isdir(cwd):
            raise FileNotFoundError(f"cwd '{cwd}' does not exist or is not a directory")

    # Validate env
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    # Build full command
    full_cmd = list(commands) + list(args)

    if verbose:
        print("Running command:", " ".join(full_cmd))

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True
        )
        if hide_stderr:
            result.stderr = ""
        return result
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command {full_cmd}: {e}") from e

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if not callable(method):
        raise TypeError("method must be callable")
    global _vcs_handlers
    if '_vcs_handlers' not in globals():
        _vcs_handlers = {}
    if vcs in _vcs_handlers:
        # Overwrite existing handler; could warn if desired
        pass
    _vcs_handlers[vcs] = method
    return method

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    if not nodes:
        return []

    # Helper to merge two MappingNode values
    def _merge_mapping(node1, node2):
        # node1 and node2 are MappingNode instances
        # Build index of existing subkeys in node1
        sub_index = {}
        for i, (subkey, subvalue) in enumerate(node1.value):
            sub_index[subkey.value] = i
        for subkey, subvalue in node2.value:
            if subkey.value in sub_index:
                i = sub_index[subkey.value]
                existing_subvalue = node1.value[i][1]
                if isinstance(existing_subvalue, MappingNode) and isinstance(subvalue, MappingNode):
                    _merge_mapping(existing_subvalue, subvalue)
                else:
                    node1.value[i] = (subkey, subvalue)
            else:
                node1.value.append((subkey, subvalue))
                sub_index[subkey.value] = len(node1.value) - 1

    result = []
    key_index = {}
    for key, value in nodes:
        # Use key.value for ScalarNode keys, otherwise use id(key) to avoid collisions
        key_id = key.value if hasattr(key, 'value') else id(key)
        if key_id in key_index:
            idx = key_index[key_id]
            existing_key, existing_value = result[idx]
            if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                _merge_mapping(existing_value, value)
            else:
                # last wins
                result[idx] = (existing_key, value)
        else:
            result.append((key, value))
            key_index[key_id] = len(result) - 1
    return result

