def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string."""
    if parser is None:
        return ''
    try:
        actions = getattr(parser, "_actions", [])
    except Exception:
        return ''
    flags = []
    for action in actions:
        try:
            opt_strings = getattr(action, "option_strings", [])
        except Exception:
            continue
        for opt in opt_strings:
            if opt:
                flags.append(opt)
    # Preserve order while removing duplicates
    seen = set()
    unique_flags = []
    for f in flags:
        if f not in seen:
            seen.add(f)
            unique_flags.append(f)
    return " ".join(unique_flags)

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    try:
        import borgmatic.main as bm_main
        if hasattr(bm_main, 'get_parser'):
            parser = bm_main.get_parser()
        else:
            raise AttributeError
    except Exception:
        try:
            import borgmatic.cli as bm_cli
            parser = bm_cli.get_parser()
        except Exception as exc:
            raise RuntimeError("Could not obtain borgmatic parser: %s" % exc)

    if not parser:
        raise RuntimeError("No parser found for borgmatic")

    subcommands = []
    sub_opts = {}
    global_opts = []

    for action in parser._actions:
        if isinstance(action, argparse._SubParsersAction):
            for name, subparser in action.choices.items():
                subcommands.append(name)
                opts = []
                for subaction in subparser._actions:
                    if subaction.option_strings:
                        opts.extend(subaction.option_strings)
                    else:
                        opts.append(subaction.dest)
                sub_opts[name] = opts
        else:
            if action.option_strings:
                global_opts.extend(action.option_strings)
            else:
                global_opts.append(action.dest)

    lines = []
    lines.append('_borgmatic() {')
    lines.append('    local cur prev words cword')
    lines.append('    _init_completion || return')
    lines.append('    local subcommands="%s"' % ' '.join(subcommands))
    lines.append('    local opts="%s"' % ' '.join(global_opts))
    lines.append('    case "$prev" in')
    for name, opts in sub_opts.items():
        lines.append('        %s)' % name)
        lines.append('            opts="%s"' % ' '.join(opts))
        lines.append('            ;;')
    lines.append('    esac')
    lines.append('    COMPREPLY=( $(compgen -W "$subcommands $opts" -- "$cur") )')
    lines.append('}')
    lines.append('complete -F _borgmatic borgmatic')
    return '\n'.join(lines)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Basic validation of inputs
    if unparsed_arguments is None:
        unparsed_arguments = []
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    if subparsers is None:
        subparsers = {}
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to ArgumentParser instances")

    parsed = {}
    remaining_lists = []

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"Parser for subparser '{name}' does not have a parse_known_args method")
        # parse_known_args never raises SystemExit; it returns (namespace, remaining)
        ns, remaining = parser.parse_known_args(unparsed_arguments)
        parsed[name] = ns
        remaining_lists.append(remaining)

    # Determine arguments not claimed by any subparser
    if remaining_lists:
        # Intersection of all remaining lists gives arguments not recognized by any parser
        intersection_set = set(remaining_lists[0])
        for lst in remaining_lists[1:]:
            intersection_set &= set(lst)
        remaining_args = [arg for arg in unparsed_arguments if arg in intersection_set]
    else:
        # No subparsers: all arguments remain
        remaining_args = list(unparsed_arguments)

    return parsed, remaining_args

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Expected an iterable of dictionaries, got None")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key {key!r} must be numeric, got {type(value).__name__}")
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is None:
        return url
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")
    import re
    from urllib.parse import quote_plus
    pattern = re.compile(r'\{([^{}]+)\}|:([A-Za-z0-9_]+)')
    def repl(match):
        key = match.group(1) or match.group(2)
        if key not in url_args:
            raise KeyError(f"Missing value for URL placeholder '{key}'")
        value = url_args[key]
        return quote_plus(str(value))
    return pattern.sub(repl, url)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None is considered a None value
    if val is None:
        return True

    # Only strings (or bytes that can be decoded) are considered for textual None representations
    if isinstance(val, str):
        s = val.strip().lower()
        # Common textual representations of None
        return s in ("none", "null", "n/a", "")
    if isinstance(val, (bytes, bytearray)):
        try:
            s = val.decode().strip().lower()
            return s in ("none", "null", "n/a", "")
        except Exception:
            return False

    # All other types are not considered None strings
    return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.
    """
    if parser is None or not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    for action in parser._actions:
        for opt in getattr(action, "option_strings", []):
            if opt.startswith("-"):
                flags.append(opt)
    # Preserve order while removing duplicates
    seen = set()
    unique_flags = []
    for f in flags:
        if f not in seen:
            seen.add(f)
            unique_flags.append(f)
    return " ".join(unique_flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("number must be an int")
    if not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise TypeError("alphabet must be a list of strings")
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")

    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols")

    # Handle negative numbers
    negative = number < 0
    n = abs(number)

    # Convert number to digits in the given base
    digits = []
    if n == 0:
        digits.append(alphabet[0])
    else:
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
    digits.reverse()
    result = ''.join(digits)

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    # Add negative sign if needed
    if negative:
        result = '-' + result

    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    subs = set()
    def _rec(c):
        for sub in c.__subclasses__():
            if sub not in subs:
                subs.add(sub)
                _rec(sub)
    _rec(cls)
    return subs

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic type checks
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")
    if not all(isinstance(c, str) for c in alphabet):
        raise TypeError("All elements of alphabet must be str")

    # Alphabet must contain at least two unique characters
    if len(alphabet) < 2:
        raise ValueError("Alphabet must contain at least two unique characters")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet must contain unique characters")

    base = len(alphabet)
    value = 0

    for char in string:
        try:
            digit = alphabet.index(char)
        except ValueError:
            raise ValueError(f"Character '{char}' not found in alphabet")
        value = value * base + digit

    return value

def unquote(name):
    """Remove quote from the given name."""
    if name is None:
        return None
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    # Use regex to strip matching surrounding quotes
    match = re.match(r"^(['\"])(.*)\1$", name)
    if match:
        return match.group(2)
    return name

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq_str = frequency.strip()
        if freq_str.lower() == 'always':
            return None
        import re
        m = re.match(r'^(\d+)\s*([a-zA-Z]+)$', freq_str)
        if not m:
            raise ValueError(f"Cannot parse frequency: {frequency!r}")
        num = int(m.group(1))
        unit = m.group(2).lower()
        unit_map = {
            'day': 'days', 'days': 'days', 'd': 'days',
            'week': 'weeks', 'weeks': 'weeks', 'w': 'weeks',
            'hour': 'hours', 'hours': 'hours', 'h': 'hours',
            'minute': 'minutes', 'minutes': 'minutes', 'min': 'minutes', 'mins': 'minutes', 'm': 'minutes',
            'second': 'seconds', 'seconds': 'seconds', 'sec': 'seconds', 'secs': 'seconds', 's': 'seconds',
        }
        if unit not in unit_map:
            raise ValueError(f"Unknown time unit in frequency: {unit!r}")
        kwargs = {unit_map[unit]: num}
        return datetime.timedelta(**kwargs)
    else:
        raise ValueError(f"Frequency must be a string or None, got {type(frequency).__name__}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    host = host.strip()
    # Quick checks for common localhost representations
    if host.lower() == 'localhost':
        return True
    if host == '127.0.0.1' or host == '::1':
        return True

    try:
        # If host is a literal IP address, check it directly
        try:
            socket.inet_pton(socket.AF_INET, host)
            return host.startswith('127.')
        except OSError:
            try:
                socket.inet_pton(socket.AF_INET6, host)
                return host == '::1'
            except OSError:
                # Not a literal IP, resolve it
                pass

        # Resolve the host and check each address
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith('127.'):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == '::1':
                    return True
        return False
    except Exception:
        # Any error (e.g., resolution failure) means we cannot confirm localhost
        return False

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    if strip:
        pattern = pattern.strip()
    # Escape all regex metacharacters to treat the string literally
    escaped = re.escape(pattern)
    # Compile the escaped pattern for efficient reuse
    return re.compile(escaped)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate and build the command list
    if isinstance(commands, str):
        cmd = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")

    cmd.extend(args)

    if verbose:
        print("Running command:", " ".join(cmd))

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            stderr=subprocess.DEVNULL if hide_stderr else None
        )
        if result.returncode != 0:
            raise subprocess.CalledProcessError(
                result.returncode, cmd, output=result.stdout, stderr=result.stderr
            )
        return result.stdout
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {cmd[0]}") from e
    except subprocess.CalledProcessError:
        raise
    except Exception as e:
        raise RuntimeError(f"Error running command {cmd}: {e}") from e

def is_ipv4(target):
    """Test if IPv4 address or not"""
    try:
        # If it's already an IPv4Address instance, it's valid
        if isinstance(target, ipaddress.IPv4Address):
            return True
        # If it's an IPv6Address instance, it's not IPv4
        if isinstance(target, ipaddress.IPv6Address):
            return False
        # Try to parse the target as an IP address
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except Exception:
        # Any error (e.g., invalid string, None, wrong type) means not a valid IPv4 address
        return False

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Validate input types
    if not isinstance(graph, rdflib.Graph):
        raise TypeError("graph must be an rdflib.Graph instance")
    if not isinstance(prop, rdflib.URIRef):
        raise TypeError("prop must be an rdflib.URIRef")
    if roots is not None and not isinstance(roots, set):
        raise TypeError("roots must be a set or None")

    children = set()
    parents = set()

    try:
        for child, _, parent in graph.triples((None, prop, None)):
            children.add(child)
            parents.add(parent)
    except Exception as exc:
        raise ValueError(f"Error iterating over graph triples: {exc}") from exc

    root_nodes = children - parents

    if roots is None:
        return root_nodes
    else:
        roots.update(root_nodes)
        return roots

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            # Use the safe dumper for a stable, non-unsafe representation
            return yaml.safe_dump(
                obj,
                default_flow_style=False,
                allow_unicode=True,
            )
        else:
            # If a custom dumper is supplied, use it directly
            return yaml.dump(
                obj,
                Dumper=dumper,
                default_flow_style=False,
                allow_unicode=True,
            )
    except yaml.YAMLError as exc:
        # Convert YAML errors into a generic ValueError for callers
        raise ValueError(f"Error dumping object to YAML string: {exc}") from exc

def build_app_logger(name='app', logfile='app.log', debug=True):
    """
    General purpose application logger. Useful mainly for debugging
    """
    # Validate inputs
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")
    if not isinstance(logfile, str):
        raise TypeError(f"logfile must be a string, got {type(logfile).__name__}")
    if not isinstance(debug, bool):
        raise TypeError(f"debug must be a bool, got {type(debug).__name__}")

    # Ensure the directory for the logfile exists
    log_dir = os.path.dirname(os.path.abspath(logfile))
    if log_dir and not os.path.exists(log_dir):
        try:
            os.makedirs(log_dir, exist_ok=True)
        except Exception as e:
            raise OSError(f"Failed to create log directory '{log_dir}': {e}")

    # Get or create the logger
    logger = logging.getLogger(name)
    logger.setLevel(logging.DEBUG if debug else logging.INFO)

    # Avoid adding duplicate handlers
    def _handler_exists(handler_type):
        return any(isinstance(h, handler_type) for h in logger.handlers)

    formatter = logging.Formatter(
        '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
    )

    # File handler
    if not _handler_exists(logging.FileHandler):
        try:
            file_handler = logging.FileHandler(logfile)
            file_handler.setLevel(logger.level)
            file_handler.setFormatter(formatter)
            logger.addHandler(file_handler)
        except Exception as e:
            raise OSError(f"Failed to create file handler for '{logfile}': {e}")

    # Stream (console) handler
    if not _handler_exists(logging.StreamHandler):
        stream_handler = logging.StreamHandler()
        stream_handler.setLevel(logger.level)
        stream_handler.setFormatter(formatter)
        logger.addHandler(stream_handler)

    return logger

def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    try:
        return np.exp(-((x - 0.2) ** 2) / (2 * 0.1 ** 2))
    except Exception as e:
        raise ValueError("Input must be a number or array-like.") from e

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import json
    import logging
    import re

    # Helper to resolve environment variables in strings
    env_var_pattern = re.compile(r'\$(\w+)|\${(\w+)}')

    def _resolve_env(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1) or match.group(2)
                return os.getenv(var, '')
            return env_var_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value

    # Validate inputs
    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError("overrides must be a dict or None")
    if not isinstance(resolve_env, bool):
        raise TypeError("resolve_env must be a bool")

    # Ensure config_filenames is iterable
    if isinstance(config_filenames, str):
        filenames = [config_filenames]
    else:
        try:
            filenames = list(config_filenames)
        except Exception as exc:
            raise TypeError("config_filenames must be a string or an iterable of strings") from exc

    results = {}
    error_records = []

    # Attempt to import yaml if available
    try:
        import yaml
        yaml_loader = yaml.safe_load
    except Exception:
        yaml_loader = None

    for fname in filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
            # Determine parser based on file extension or content
            if yaml_loader and fname.lower().endswith(('.yaml', '.yml')):
                parsed = yaml_loader(content)
            else:
                parsed = json.loads(content)
            if not isinstance(parsed, dict):
                raise ValueError("Parsed configuration is not a dictionary")
            # Apply overrides if provided
            if overrides:
                parsed.update(overrides)
            # Resolve environment variables if requested
            if resolve_env:
                parsed = _resolve_env(parsed)
            results[fname] = parsed
        except FileNotFoundError as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"File not found: {fname}",
                args=None,
                exc_info=exc
            )
            error_records.append(record)
            results[fname] = None
        except (json.JSONDecodeError, ValueError, yaml.YAMLError) as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Error parsing configuration file {fname}: {exc}",
                args=None,
                exc_info=exc
            )
            error_records.append(record)
            results[fname] = None
        except Exception as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Unexpected error loading {fname}: {exc}",
                args=None,
                exc_info=exc
            )
            error_records.append(record)
            results[fname] = None

    return results, error_records

def force_string(obj):
    """This function returns the bytes object corresponding to ``obj`` in case it is a string using UTF-8."""
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as e:
            raise ValueError(f"Error encoding string to UTF-8: {e}") from e
    elif isinstance(obj, (bytes, numpy.bytes_)):
        return obj
    else:
        raise TypeError(f"force_string expects a string or bytes, got {type(obj).__name__}")

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values cannot be None")

    # If a single string is passed, treat it as a single bookmark
    if isinstance(values, str):
        raw_list = [values]
    else:
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")

        raw_list = []
        for v in iterator:
            if not isinstance(v, str):
                raise TypeError(f"Bookmark value must be a string, got {type(v).__name__}")
            raw_list.append(v)

    # Create a new instance of the class
    try:
        obj = cls()
    except Exception as exc:
        raise RuntimeError(f"Failed to instantiate {cls.__name__}: {exc}") from exc

    # Store the raw values in a standard attribute if possible
    if hasattr(obj, "bookmarks"):
        obj.bookmarks = raw_list
    elif hasattr(obj, "values"):
        obj.values = raw_list
    else:
        # Fallback: set a generic attribute
        setattr(obj, "bookmarks", raw_list)

    return obj

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, use it after validation
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a class")
        return explicit_mc

    # No bases provided – default to the built‑in type
    if not bases:
        return type

    # Ensure all bases are classes
    for b in bases:
        if not isinstance(b, type):
            raise TypeError("all bases must be classes")

    # Gather the metaclasses of each base
    metaclasses = [type(b) for b in bases]

    # If all metaclasses are identical, return that one
    if all(mc is metaclasses[0] for mc in metaclasses):
        return metaclasses[0]

    # Find a metaclass that is a subclass of all others
    for mc in metaclasses:
        if all(issubclass(mc, other) for other in metaclasses):
            return mc

