def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    # Try to locate a usage counter; common names are `_usage` or `usage`
    usage = getattr(self, '_usage', None)
    if usage is None:
        usage = getattr(self, 'usage', None)
    # If no usage information is available, fall back to the default popitem
    if usage is None:
        return super().popitem()
    # Find the key with the smallest usage count
    min_key = None
    min_count = None
    for k in self:
        count = usage.get(k, 0)
        if min_count is None or count < min_count:
            min_count = count
            min_key = k
    if min_key is None:
        raise KeyError('popitem(): dictionary is empty')
    # Remove the key from the dictionary and its usage counter
    value = self.pop(min_key)
    if min_key in usage:
        del usage[min_key]
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Try to use the OrderedDict style popitem which accepts a `last` argument.
    try:
        return self.popitem(last=True)
    except TypeError:
        # Fallback to the standard dict popitem (which removes the last inserted item in Python 3.7+).
        return self.popitem()

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False

        # Check for public message
        if getattr(request, "public", None):
            return True
        if isinstance(request, dict) and request.get("public"):
            return True

        # Check for private message
        if getattr(request, "private", None):
            return True
        if isinstance(request, dict) and request.get("private"):
            return True

        # Check legacy payload
        if getattr(request, "legacy", None):
            return True
        if isinstance(request, dict) and request.get("legacy"):
            return True

        # Check headers for Diaspora specific markers
        headers = getattr(request, "headers", None)
        if isinstance(headers, dict):
            if headers.get("X-Diaspora") or headers.get("diaspora"):
                return True

        # Check body content for Diaspora keyword
        body = getattr(request, "body", None)
        if isinstance(body, str) and "diaspora" in body.lower():
            return True

        return False
    except Exception:
        # In case of any unexpected error, conservatively return False
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Handle dictionary-like requests
        if isinstance(request, dict):
            # Check for a 'type' key
            req_type = request.get('type')
            if isinstance(req_type, str) and req_type.lower() == 'matrix':
                return True
            # Check for a 'matrix' key
            if 'matrix' in request:
                return True
            # Check headers for content type
            headers = request.get('headers')
            if isinstance(headers, dict):
                content_type = headers.get('Content-Type') or headers.get('content-type')
                if isinstance(content_type, str) and 'matrix' in content_type.lower():
                    return True
            return False

        # Handle object-like requests
        # Check for a 'type' attribute
        req_type = getattr(request, 'type', None)
        if isinstance(req_type, str) and req_type.lower() == 'matrix':
            return True

        # Check for a 'matrix' attribute
        if getattr(request, 'matrix', None):
            return True

        # Check for a 'method' attribute
        method = getattr(request, 'method', None)
        if isinstance(method, str) and method.lower() == 'matrix':
            return True

        # Check headers attribute if present
        headers = getattr(request, 'headers', None)
        if isinstance(headers, dict):
            content_type = headers.get('Content-Type') or headers.get('content-type')
            if isinstance(content_type, str) and 'matrix' in content_type.lower():
                return True

        return False
    except Exception:
        # Any unexpected error results in a conservative False
        return False

