def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise TypeError("node cannot be None")
    # Ensure node is an Element-like object
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError(f"Provided node does not support iteration over children: {exc}") from exc

    result = {}
    for child in children:
        # Use the tag name as key; keep namespace if present
        key = child.tag
        if key in result:
            # If already a list, append; otherwise convert to list
            existing = result[key]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[key] = [existing, child]
        else:
            result[key] = child
    return result

