    else:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string if provided")
        # If the document_path is an absolute URL, use it directly
        if document_path.startswith("http://") or document_path.startswith("https://"):
            href = document_path
        else:
            # Ensure proper joining of base and path
