def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate input
    if not isinstance(handle, str) or not handle.strip():
        raise ValueError("handle must be a non-empty string")

    handle = handle.strip()

    # Strip the optional 'acct:' prefix
    if handle.lower().startswith("acct:"):
        handle = handle[5:]

    # Ensure the handle contains a user and domain part
    if "@" not in handle:
        raise ValueError("handle must be in the form 'user@domain'")

    user, domain = handle.split("@", 1)
    if not user or not domain:
        raise ValueError("handle must contain both a user and a domain")

    # Construct the webfinger URL
    url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"

    # Import requests lazily
    try:
        import requests
    except ImportError as exc:
        raise ImportError("The 'requests' library is required to retrieve webfinger documents") from exc

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.exceptions.RequestException as exc:
        raise RuntimeError(f"Failed to retrieve webfinger document from {url}") from exc

    # Parse JSON response
    try:
        data = response.json()
    except ValueError as exc:
        raise ValueError(f"Failed to parse JSON from webfinger response at {url}") from exc

    if not isinstance(data, dict):
        raise ValueError(f"Unexpected response format from {url}: expected a JSON object")

    return data

def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not isinstance(host, str):
        raise TypeError("host must be a string")
    host = host.strip()
    if not host:
        raise ValueError("host must not be empty")

    # Strip any scheme prefix
    if host.lower().startswith("http://"):
        host = host[7:]
    elif host.lower().startswith("https://"):
        host = host[8:]

    url = f"https://{host}/.well-known/host-meta"

    try:
        import urllib.request
        import urllib.error
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                raise ValueError(f"Failed to retrieve host-meta: HTTP {resp.status}")
            data = resp.read()
    except urllib.error.HTTPError as e:
        raise ValueError(f"HTTP error retrieving host-meta: {e.code}") from e
    except urllib.error.URLError as e:
        raise ValueError(f"URL error retrieving host-meta: {e.reason}") from e
    except Exception as e:
        raise ValueError(f"Error retrieving host-meta: {e}") from e

    # Decode bytes to string if necessary
    if isinstance(data, bytes):
        try:
            data = data.decode("utf-8")
        except Exception as e:
            raise ValueError(f"Failed to decode host-meta response: {e}") from e

    # Create and return an XRD instance
    try:
        # Assume XRD can be constructed from an XML string
        return XRD(data)
    except Exception as e:
        raise ValueError(f"Error creating XRD instance: {e}") from e

