@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Import yaml lazily to avoid unnecessary dependency if not used
        try:
            import yaml
        except ImportError as exc:
            raise IRValidatorException("YAML parser not available") from exc

        if spec_content is None:
            raise IRValidatorException("Spec content is None")

        # If the content is a string or bytes, attempt to parse it as YAML
        if isinstance(spec_content, (bytes, bytearray)):
            try:
                spec_content = spec_content.decode('utf-8')
            except Exception as exc:
                raise IRValidatorException("Spec content bytes could not be decoded") from exc

        if isinstance(spec_content, str):
            try:
                spec_dict = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException("Failed to parse YAML content") from exc
        elif isinstance(spec_content, dict):
            spec_dict = spec_content
        else:
            raise IRValidatorException(f"Unsupported spec content type: {type(spec_content).__name__}")

        if not isinstance(spec_dict, dict):
            raise IRValidatorException("Parsed spec content is not a mapping")

        # Determine required fields; subclasses may define REQUIRED_FIELDS
        required_fields = getattr(cls, "REQUIRED_FIELDS", None)
        if required_fields is None:
            # If no explicit list, assume no validation needed
            return spec_dict

        if not isinstance(required_fields, (list, tuple, set)):
            raise IRValidatorException("REQUIRED_FIELDS must be a list, tuple, or set")

        missing = [field for field in required_fields if field not in spec_dict]
        if missing:
            raise IRValidatorException(f"Missing required field(s) in spec: {', '.join(missing)}")

        return spec_dict

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file must be provided")

        # Accept both string paths and pathlib.Path objects
        try:
            from pathlib import Path
        except Exception:
            raise IRValidatorException("pathlib module is required for file handling")

        path = Path(yaml_file)
        if not path.is_file():
            raise IRValidatorException(f"YAML file not found: {yaml_file}")

        try:
            import yaml
        except Exception:
            raise IRValidatorException("PyYAML is required to load YAML files")

        try:
            with path.open("r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except Exception as exc:
            raise IRValidatorException(f"Error loading YAML file: {exc}") from exc

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file must contain a mapping at the top level")

        # If the class defines a list of required keys, enforce them
        required_keys = getattr(cls, "REQUIRED_KEYS", [])
        if required_keys:
            missing = [k for k in required_keys if k not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing required keys in YAML file: {', '.join(missing)}"
                )

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dictionary")
    resolved = {}
    # keep track of groups that are currently being resolved to detect cycles
    resolving = set()

    def _resolve_group(name):
        if name in resolved:
            return resolved[name]
        if name in resolving:
            raise ValueError(f"Circular include detected while resolving group '{name}'")
        if name not in parser_dict:
            raise ValueError(f"Included group '{name}' not found in parser_dict")
        resolving.add(name)
        group = parser_dict[name]
        if not isinstance(group, dict):
            raise TypeError(f"Group '{name}' must be a dictionary, got {type(group).__name__}")
        # start with an empty dict for the resolved group
        result = {}
        # handle include directive first
        includes = group.get("include")
        if includes is not None:
            if isinstance(includes, str):
                includes = [includes]
            if not isinstance(includes, (list, tuple)):
                raise TypeError(f"Include value for group '{name}' must be a string or list/tuple of strings")
            for inc_name in includes:
                if not isinstance(inc_name, str):
                    raise TypeError(f"Included group name must be a string, got {type(inc_name).__name__}")
                inc_resolved = _resolve_group(inc_name)
                # merge included group's keys; later keys will override earlier ones
                result.update(inc_resolved)
        # merge the current group's own keys, overriding any included ones
        for k, v in group.items():
            if k == "include":
                continue
            result[k] = v
        resolving.remove(name)
        resolved[name] = result
        return result

    for group_name in parser_dict:
        _resolve_group(group_name)
    return resolved

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Ensure the instance has a spec attribute that is a dictionary
    try:
        spec = getattr(self, 'spec')
    except AttributeError:
        raise AttributeError("Instance has no 'spec' attribute")
    if not isinstance(spec, dict):
        raise TypeError("'spec' attribute must be a dict")

    # Optional defaults dictionary that may be defined on the instance
    defaults_source = getattr(self, 'defaults', {})
    if not isinstance(defaults_source, dict):
        defaults_source = {}

    # Environment variables are considered a fallback source
    import os

    resolved_defaults = {}
    for key, value in spec.items():
        if value is None:
            # 1. Check the instance's defaults dictionary
            default = defaults_source.get(key)
            # 2. If not found, try an environment variable (upper‑cased key)
            if default is None:
                env_val = os.getenv(key.upper())
                if env_val is not None:
                    default = env_val
            resolved_defaults[key] = default
    return resolved_defaults

