def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checking
    if not isinstance(cli_args, dict):
        raise TypeError("cli_args must be a dictionary")
    if not isinstance(answer_file_args, dict):
        raise TypeError("answer_file_args must be a dictionary")

    # Retrieve the mapping of deprecated arguments if it exists
    deprecated = getattr(self, "deprecated_args", {})
    if not isinstance(deprecated, dict):
        deprecated = {}

    # Helper to format and print a deprecation warning
    def _warn(arg, source):
        new = deprecated.get(arg)
        msg = f"Argument '{arg}' from {source} is deprecated"
        if new:
            msg += f" and will be replaced by '{new}'"
        msg += "."
        print(msg)

    # Check CLI arguments
    for arg in cli_args:
        if arg in deprecated:
            _warn(arg, "CLI")

    # Check answer file arguments
    for arg in answer_file_args:
        if arg in deprecated:
            _warn(arg, "answer file")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not command_name.strip():
        raise ValueError("command_name cannot be empty or whitespace")

    # Retrieve the options dictionary; raise informative errors if missing
    try:
        options_dict = getattr(self, "_command_options")
    except AttributeError:
        raise AttributeError(
            "The object does not have a '_command_options' attribute "
            "which should map command names to option specifications."
        )

    # Normalise command name to lower case for case‑insensitive lookup
    key = command_name.lower()

    try:
        options = options_dict[key]
    except KeyError:
        raise KeyError(f"No options found for command '{command_name}'")

    # Ensure the returned value is iterable; otherwise raise a clear error
    if not hasattr(options, "__iter__"):
        raise TypeError(
            f"The options for command '{command_name}' are not iterable "
            f"(got {type(options).__name__})"
        )

    # Return a shallow copy to prevent accidental mutation of the internal state
    return list(options)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    # Ensure the object has a commands mapping
    if not hasattr(self, "commands"):
        raise AttributeError("The object does not have a 'commands' attribute")

    # Retrieve the command object
    command = self.commands.get(command_name)
    if command is None:
        raise ValueError(f"Command '{command_name}' not found")

    # Retrieve the options mapping from the command
    options = getattr(command, "options", None)
    if options is None:
        raise AttributeError(f"Command '{command_name}' has no 'options' attribute")

    # Retrieve the specification for the requested argument
    spec = options.get(argument_name)
    if spec is None:
        raise ValueError(f"Option '{argument_name}' not found in command '{command_name}'")

    return spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    try:
        # If args is a mapping, check for None or empty values
        if isinstance(args, dict):
            for key, value in args.items():
                if value is None or value == '':
                    silent.append(key)
        else:
            # Assume an iterable of (name, value) tuples or just names
            for item in args:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    name, value = item
                    if value is None or value == '':
                        silent.append(name)
                else:
                    # If only a name is provided, treat it as silent
                    silent.append(item)
    except Exception as exc:
        raise ValueError(f"Invalid args format: {exc}") from exc
    return silent

def validate_requires_args(self, args):
