def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Normalise args to a dictionary for evaluation
        if isinstance(args, dict):
            args_dict = args
        else:
            try:
                args_dict = vars(args)
            except Exception:
                args_dict = {}

        required = []

        for opt in options_spec:
            # Skip if no name or no condition
            name = opt.get('name')
            if not name:
                continue
            cond = opt.get('required_when')
            if cond is None:
                continue

            matched = False
            try:
                if callable(cond):
                    # If it's a function, call it with args dict
                    matched = bool(cond(args_dict))
                elif isinstance(cond, str):
                    # Evaluate the string expression in a safe namespace
                    matched = bool(eval(cond, {}, args_dict))
                else:
                    # Unsupported type, treat as False
                    matched = False
            except Exception:
                # Any error in evaluation means condition not met
                matched = False

            if matched:
                required.append(name)

        return required

