        max_len = max_lengths.get(key)
        if max_len is None:
            continue
        if not isinstance(max_len, int) or max_len < 0:
            # Invalid max_len definition; ignore this argument
            continue

        # Determine the length of the value if it is a string, list, tuple, or set
        if isinstance(value, (str, list, tuple, set)):
            val_len = len(value)
        else:
            # For other types, we cannot determine length; skip
            continue

        if val_len > max_len:
            raise ValueError(
                f"Argument '{key}' exceeds maximum length of {max_len} "
                f"(got {val_len})"
            )
    # If no exception was raised, all arguments are within allowed lengths
    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Basic input validation
    if args is None:
        raise TypeError("args must not be None")
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument names to values")

    # Ensure the object has a 'choices' attribute
    if not hasattr(self, "choices"):
        raise AttributeError("The object does not have a 'choices' attribute")
    if not isinstance(self.choices, dict):
        raise TypeError("self.choices must be a dict mapping argument names to allowed values")

    for key, value in args.items():
        # Skip arguments that have no defined choices
        if key not in self.choices:
            continue

        allowed = self.choices[key]

        # If allowed is a callable, use it to validate
        if callable(allowed):
            try:
                if not allowed(value):
                    raise ValueError(f"Invalid choice for argument '{key}': {value}")
            except Exception as exc:
                raise ValueError(f"Error validating choice for argument '{key}': {exc}") from exc
            continue

        # Treat allowed as an iterable of valid values (list, tuple, set, etc.)
        if isinstance(allowed, (list, tuple, set)):
            # If the provided value is itself an iterable (but not a string), validate each element
            if isinstance(value, (list, tuple, set)) and not isinstance(value, str):
                for v in value:
                    if v not in allowed:
                        raise ValueError(
                            f"Invalid choice for argument '{key}': {v}. Allowed: {allowed}"
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid choice for argument '{key}': {value}. Allowed: {allowed}"
                    )
        else:
            # If allowed is a single value, compare directly
            if value != allowed:
                raise ValueError(
                    f"Invalid choice for argument '{key}': {value}. Expected: {allowed}"
                )

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Retrieve global min and max bounds if defined on the instance
    min_val = getattr(self, 'MIN', None)
    max_val = getattr(self, 'MAX', None)

    # If no bounds are defined, nothing to validate
    if min_val is None or max_val is None:
        return True

    # Ensure min_val <= max_val
    try:
        if min_val > max_val:
            raise ValueError(f"Invalid bounds: MIN ({min_val}) > MAX ({max_val})")
    except TypeError:
        raise TypeError(f"MIN ({min_val}) and MAX ({max_val}) must be comparable")

    # Determine the iterable of values to check
    if isinstance(args, dict):
        values = args.values()
    elif isinstance(args, (list, tuple, set)):
        values = args
    else:
        # Treat a single non-iterable argument as a single value
        values = [args]

    # Validate each value
    for val in values:
        # Skip None values (could be optional arguments)
        if val is None:
            continue
        try:
            if val < min_val or val > max_val:
                raise ValueError(
                    f"Argument value {val!r} out of bounds [{min_val!r}, {max_val!r}]"
                )
        except TypeError:
            raise TypeError(
                f"Argument value {val!r} is not comparable to bounds {min_val!r} and {max_val!r}"
            )

    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Basic validation of inputs
        if not isinstance(subcommand, str):
            raise TypeError("subcommand must be a string")
        if not isinstance(type_name, str):
            raise TypeError("type_name must be a string")
        if not isinstance(option_name, str):
            raise TypeError("option_name must be a string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dict")

        # Helper to resolve the expected type
        def resolve_type(t):
            if isinstance(t, str):
                mapping = {
                    'int': int,
                    'float': float,
                    'bool': lambda v: v.lower() in ('true', '1', 'yes', 'on'),
                    'str': str,
                }
                if t.lower() not in mapping:
                    raise ValueError(f"Unsupported type specifier: {t}")
                return mapping[t.lower()]
            if isinstance(t, type):
                return t
            raise TypeError(f"Invalid type specification: {t}")

        # Define the complex argument type as a callable
        class ComplexArgumentType:
            def __init__(self, subcommand, type_name, option_name, spec_option):
                self.subcommand = subcommand
                self.type_name = type_name
                self.option_name = option_name
                self.spec_option = spec_option
                # Resolve the expected type once
                self._expected_type = resolve_type(spec_option.get('type', str))

            def __call__(self, value):
                # Convert the value to the expected type
                try:
                    converted = self._expected_type(value)
                except Exception as exc:
                    raise ValueError(f"Invalid value for {self.option_name}: {exc}") from exc

                # Validate against choices if provided
                choices = self.spec_option.get('choices')
                if choices is not None and converted not in choices:
                    raise ValueError(f"Value for {self.option_name} must be one of {choices}")

                # Validate numeric bounds if applicable
                if isinstance(converted, (int, float)):
                    min_val = self.spec_option.get('min')
                    max_val = self.spec_option.get('max')
                    if min_val is not None and converted < min_val:
                        raise ValueError(f"Value for {self.option_name} must be >= {min_val}")
                    if max_val is not None and converted > max_val:
                        raise ValueError(f"Value for {self.option_name} must be <= {max_val}")

                return converted

            def __repr__(self):
                return f"<ComplexArgumentType {self.type_name} for {self.option_name}>"

        return ComplexArgumentType(subcommand, type_name, option_name, spec_option)

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare result dictionaries
    control_args = {}
    nested_args = {}

    # If args is None or empty, return empty dicts
    if not args:
        return control_args, nested_args

    # Helper to process a key/value pair
    def _add_pair(key, value):
        if not isinstance(key, str):
            raise TypeError(f"Argument key must be a string, got {type(key).__name__}")
        # Define control keys: those starting with '_' or 'control_'
        if key.startswith('_') or key.startswith('control_'):
            control_args[key] = value
        else:
            nested_args[key] = value

    # If args is a mapping (dict-like)
    if isinstance(args, dict):
        for k, v in args.items():
            _add_pair(k, v)
    # If args is an iterable of pairs (e.g., list of tuples)
    else:
        try:
            iterator = iter(args)
        except TypeError:
            raise TypeError(f"args must be a dict or an iterable of key/value pairs, got {type(args).__name__}")
        for item in iterator:
            if not isinstance(item, (list, tuple)) or len(item) != 2:
                raise ValueError(f"Each item in args must be a 2-element sequence, got {item!r}")
            k, v = item
            _add_pair(k, v)

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict

    # Helper to add a single key/value pair
    def _add(k, v):
        if k is None or k == "":
            return
        vars_dict[k] = v

    # If extra_vars is a mapping, update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    # If it's a string, try to parse a single key=value pair
    elif isinstance(extra_vars, str):
        if "=" in extra_vars:
            k, v = extra_vars.split("=", 1)
            _add(k.strip(), v.strip())
    # If it's an iterable (but not a string), iterate over items
    else:
        try:
            iterator = iter(extra_vars)
        except TypeError:
            raise TypeError("extra_vars must be a dict, string, or iterable")
        for item in iterator:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, (list, tuple)):
                if len(item) == 2:
                    k, v = item
                    _add(k, v)
            elif isinstance(item, str):
                if "=" in item:
                    k, v = item.split("=", 1)
                    _add(k.strip(), v.strip())
            # ignore any other types

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import json
    import subprocess

    # Validate playbook path
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook file not found: {playbook_path}")

    # Build base command
    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose < 0:
                raise ValueError("verbose level must be non-negative")
            cmd.extend(["-v" * verbose])
        elif isinstance(verbose, str):
            # Accept strings like 'v', 'vv', etc.
            if not all(c == 'v' for c in verbose):
                raise ValueError("verbose string must consist of 'v' characters")
            cmd.append(verbose)
        else:
            raise TypeError("verbose must be int or str")

    # Handle ansible_args
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                raise TypeError("ansible_args keys must be strings")
            flag = f"--{key.lstrip('-')}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                # if False, skip adding the flag
            elif value is None:
                # treat None as flag without value
                cmd.append(flag)
            else:
                cmd.append(f"{flag}={value}")

    # Handle extra_vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            json_str = json.dumps(extra_vars, separators=(',', ':'))
        except (TypeError, ValueError) as exc:
            raise ValueError(f"extra_vars could not be serialized to JSON: {exc}") from exc
        cmd.extend(["--extra-vars", json_str])

    # Optional: log the command for debugging
    try:
        if hasattr(ir_plugin, "logger"):
            ir_plugin.logger.debug(f"Running ansible-playbook command: {' '.join(cmd)}")
    except Exception:
        # ignore any logging errors
        pass

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as exc:
        # Include stdout and stderr in the error message
        msg = (
            f"ansible-playbook failed with return code {exc.returncode}\n"
            f"Command: {' '.join(exc.cmd)}\n"
            f"Stdout:\n{exc.stdout}\n"
            f"Stderr:\n{exc.stderr}"
        )
        raise RuntimeError(msg) from exc
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found. "
                           "Ensure Ansible is installed and in PATH.") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error running ansible-playbook: {exc}") from exc

    # Return the captured stdout
    return result.stdout

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    from pathlib import Path

    # Resolve plugin directory
    try:
        plugin_path = Path(plugin_dir).expanduser().resolve(strict=True)
    except Exception as exc:
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' does not exist or cannot be accessed.") from exc

    # Possible spec file names
    spec_filenames = [
        "plugin.yaml", "plugin.yml",
        "plugin.json",
        "spec.yaml", "spec.yml",
        "spec.json",
    ]

    spec_file = None
    for name in spec_filenames:
        candidate = plugin_path / name
        if candidate.is_file():
            spec_file = candidate
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_path}'. Expected one of: {', '.join(spec_filenames)}")

    # Load spec content
    try:
        with spec_file.open("r", encoding="utf-8") as f:
            content = f.read()
    except Exception as exc:
        raise IOError(f"Failed to read spec file '{spec_file}'.") from exc

    # Try YAML first, fallback to JSON
    spec_data = None
    try:
        import yaml
        spec_data = yaml.safe_load(content)
    except Exception:
        try:
            spec_data = json.loads(content)
        except Exception as exc:
            raise ValueError(f"Spec file '{spec_file}' is neither valid YAML nor JSON.") from exc

    if not isinstance(spec_data, dict):
        raise ValueError(f"Spec file '{spec_file}' does not contain a top-level dictionary.")

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            if not isinstance(k, str):
                raise ValueError(f"Spec key '{k}' is not a string.")
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(spec_data)
